import React from "react";

export default function Allservices() {
  const services = [
    {
      title: "Web Development",
      description:
        "We create high-performance, responsive, and visually appealing websites that drive engagement and conversions.",
      image: "https://source.unsplash.com/600x400/?website,technology",
    },
    {
      title: "Mobile App Development",
      description:
        "We build intuitive and user-friendly mobile apps tailored to your business needs, compatible with iOS and Android.",
      image: "https://source.unsplash.com/600x400/?mobile,app",
    },
    {
      title: "UI/UX Design",
      description:
        "We design clean, modern, and engaging interfaces that ensure an excellent user experience and strong brand identity.",
      image: "https://source.unsplash.com/600x400/?design,uiux",
    },
  ];

  return (
    <div className="bg-gray-50 py-12">
      <div className="max-w-6xl mx-auto px-4 space-y-16">
        {services.map((service, index) => (
          <div
            key={index}
            className={`flex flex-col md:flex-row items-center gap-10 ${
              index % 2 !== 0 ? "md:flex-row-reverse" : ""
            }`}
          >
            {/* Image */}
            <div className="md:w-1/2 relative group">
              <img
                src={service.image}
                alt={service.title}
                className="rounded-2xl shadow-lg transform group-hover:scale-105 transition duration-500"
              />
              <div className="absolute inset-0 rounded-2xl bg-gradient-to-tr from-purple-500/30 to-transparent opacity-0 group-hover:opacity-100 transition"></div>
            </div>

            {/* Content */}
            <div className="md:w-1/2 space-y-4">
              <h2 className="text-3xl font-bold text-gray-800">{service.title}</h2>
              <p className="text-gray-600 leading-relaxed">{service.description}</p>
              <button className="px-6 py-3 bg-purple-600 text-white rounded-xl shadow-md hover:bg-purple-700 transition">
                Learn More
              </button>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}
